# Source for q/ae-views-measure4.js: Measurements (normal values, grading, tracing) + Echo views (TEE, special windows) + Stress echo.
M="Measurements"; V="Echo views"; S="Stress echo"
Q=[
# --- Normal values ---
(M,"Normal LVEF (2D biplane) in adult women is about:","54% to 74%",["30% to 40%","40% to 50%","80% to 95%"],"In men the normal range is about 52% to 72%.","F"),
(M,"Normal mid RV diameter (RV-focused apical view) is up to about:","35 mm",["55 mm","20 mm","70 mm"],"The basal RV diameter is normally up to about 41 mm.","C"),
(M,"Normal RV length (base to apex) is up to about:","83 mm",["40 mm","120 mm","60 mm"],"Measure in the RV-focused apical four-chamber view.","C"),
(M,"The distal RVOT diameter (PSAX, just before the pulmonic valve) is normally up to about:","27 mm",["40 mm","15 mm","50 mm"],"A dilated RVOT suggests volume or pressure overload.","C"),
(M,"Normal main pulmonary artery diameter is under about:","25 mm",["40 mm","10 mm","50 mm"],"A PA larger than the aorta suggests PH.","F"),
(M,"3D RV ejection fraction is abnormal when below about:","45%",["20%","70%","90%"],"3D RVEF avoids geometric assumptions about the RV shape.","C"),
(M,"Reduced LA reservoir strain (under about 18%) suggests:","Raised LV filling pressure",["Normal filling","Pericardial effusion","Aortic stenosis only"],"LA strain is a newer marker used in diastolic assessment.","C"),
(M,"A septal E/e′ over about 15 or a lateral E/e′ over about 13 suggests:","Raised LV filling pressure",["Normal filling","Low LA pressure","Normal aging only"],"Using the average of septal and lateral (over 14) is preferred.","C"),
(M,"A mitral deceleration time under about 160 ms in a patient with reduced EF suggests:","Restrictive filling with high LA pressure",["Normal filling","Impaired relaxation","Low LA pressure"],"Short DT reflects a stiff LV that quickly equalizes with the LA.","C"),
(M,"A normal mitral E velocity in adults is roughly:","0.6 to 1.3 m/s",["2 to 3 m/s","0.1 to 0.2 m/s","4 to 5 m/s"],"Values change with age, loading and heart rate.","F"),
(M,"In young healthy adults, pulmonary vein flow typically shows:","A larger D wave than S wave",["No D wave","Large Ar over 50 cm/s","Systolic reversal"],"With aging, S becomes larger than D.","C"),
# --- Grading ---
(M,"An MR color jet occupying more than 40% of the LA area suggests:","Severe MR (central jets)",["Mild MR","Trace MR","No MR"],"Jet area is affected by settings and eccentric jets.","F"),
(M,"A TR jet area over 10 cm² suggests:","Severe TR",["Mild TR","Trace TR","Normal"],"Use with vena contracta, PISA and hepatic flow.","F"),
(M,"A TR EROA of 0.4 cm² or more by PISA suggests:","Severe TR",["Mild TR","Moderate TR","No TR"],"Newer grades extend above severe.","C"),
(M,"End-diastolic velocity of the holodiastolic reversal in the descending aorta over about 20 cm/s suggests:","Severe AR",["Mild AR","Normal","Mitral stenosis"],"Measure with PW in the proximal descending aorta from the suprasternal view.","C"),
(M,"An AR pressure half-time over 500 ms suggests:","Mild AR",["Severe AR","Moderate to severe AR","Acute severe AR"],"Under 200 ms suggests severe AR.","F"),
(M,"Severe mitral stenosis is usually defined by a valve area of:","1.5 cm² or less",["3.0 cm² or less","2.5 cm² or less","0.5 cm² or more"],"Very severe MS is 1.0 cm² or less.","F"),
(M,"An MR regurgitant fraction under 30% suggests:","Mild MR",["Severe MR","Moderate to severe MR","Flail leaflet"],"30% to 49% is moderate; 50% or more is severe.","F"),
(M,"A pericardial effusion over 20 mm in diastole is graded as:","Large",["Small","Trivial","Moderate"],"Under 10 mm is small; 10 to 20 mm is moderate.","F"),
# --- Tracing and technique ---
(M,"When tracing an LVOT PW Doppler signal for VTI, the sonographer should trace:","The modal velocity (the bright, dense outer edge)",["The faint, outermost noise","The baseline","Only the peak point"],"Tracing faint edges overestimates the VTI.","F"),
(M,"When measuring an AS jet by CW, fine linear 'feathering' beyond the dense envelope should be:","Ignored; trace the outer edge of the dense signal",["Included in the peak","Used as the true peak","Measured as the mean"],"Feathering comes from transit time effect and noise.","C"),
(M,"If the LVOT PW signal aliases or shows a high-velocity spike near the aortic valve, the sample volume should be:","Moved slightly back toward the apex until flow is laminar",["Moved into the aorta","Made much larger","Left in place"],"The gate should be in laminar flow just before flow acceleration.","F"),
(M,"When E and A waves are fused because of fast heart rate, E/A is not reported if the E velocity at the start of A is more than about:","20 cm/s",["100 cm/s","1 cm/s","5 m/s"],"Fusion makes E/A unreliable; use other parameters.","C"),
(M,"For e′, the ASE recommends using:","The average of septal and lateral e′ when possible",["Septal only always","Lateral only always","The RV annulus"],"Regional wall motion problems can affect a single site.","F"),
(M,"For mean gradient across a valve, the sonographer should:","Trace the full Doppler envelope; the machine averages instantaneous gradients",["Square the mean velocity","Use only the peak velocity","Measure the PHT"],"Mean gradient is not 4 × (mean velocity)².","C"),
(M,"In a ventilated patient, an IVC distensibility index over about 18% suggests:","The patient may be fluid responsive",["Severe fluid overload","Tamponade always","High RA pressure"],"IVC behaves differently under positive pressure ventilation.","C"),
(M,"Variation in LVOT VTI of more than about 12% with breathing or after leg raising suggests:","Fluid responsiveness",["Fluid overload","Normal hearts never vary","Tamponade only"],"It is used to guide fluid therapy in the ICU.","C"),
(M,"In hypertrophic obstructive cardiomyopathy, the LVOT gradient should be measured:","At rest and with Valsalva, and on standing if needed",["Only at rest","Only under general anesthesia","Never"],"Provocation can show hidden obstruction.","F"),
(M,"Planimetry of mitral stenosis should be done:","At the leaflet tips in mid-diastole, in a true PSAX plane",["At the annulus","In systole","In the apical view"],"Off-axis cuts above the tips overestimate the area.","F"),
(M,"A 3D measurement of LV mass may be preferred over linear methods because:","It does not depend on shape assumptions",["It is always faster","It needs no image quality","It is the same as M-mode"],"Linear methods assume a regular ellipsoid shape.","F"),
(M,"For TR peak velocity, if the signal is weak, the sonographer can:","Try several windows and use agitated saline to enhance the signal",["Use the first beat only","Assume RVSP is normal","Use LVOT VTI"],"Saline brightens the TR envelope.","F"),
(M,"The aortic root measurement should be made perpendicular to:","The long axis of the aorta",["The ultrasound beam always","The LV septum","The pulmonary artery"],"Oblique cuts overestimate diameters.","F"),
(M,"LA area in the apical four-chamber view over about 20 cm² suggests:","LA enlargement",["Normal LA","Small LA","LA thrombus"],"Volume indexed to BSA is the preferred measure.","C"),
(M,"Combining TR peak velocity with other signs, such as RV dilation, helps estimate:","The probability of pulmonary hypertension",["LV mass","Aortic valve area","LA volume"],"Other RV, PA and IVC signs refine the probability.","F"),
# --- TEE and special views ---
(V,"The TEE transgastric two-chamber view at about 90° shows:","The LV inferior and anterior walls and mitral subvalvular apparatus",["The aortic arch","The PA bifurcation","The LAA only"],"It is good for seeing chordae and papillary muscles.","C"),
(V,"The TEE upper esophageal aortic arch long-axis view is obtained at about:","0°",["90°","135°","60°"],"Rotating to 90° gives the arch short axis with the PA and pulmonic valve.","C"),
(V,"The TEE upper esophageal aortic arch short-axis view (about 90°) is useful for:","Doppler of the pulmonic valve and main PA",["Mitral planimetry","Measuring LV mass","The LV apex"],"Flow in the PA is nearly parallel to the beam.","C"),
(V,"The TEE descending aortic short-axis view is obtained by:","Turning the probe to the left from the mid-esophageal four-chamber view at 0°",["Advancing into the stomach","Turning to the right","Rotating to 135°"],"Withdraw and advance to follow the aorta.","C"),
(V,"For LAA thrombus on TEE, the appendage should be imaged at:","Several angles (for example 0°, 45°, 90° and 135°)",["Only 0°","Only 180°","One angle only"],"The appendage has several lobes that can hide clot.","F"),
(V,"The TEE transgastric RV inflow view shows:","The RV and RA with the tricuspid valve and subvalvular apparatus",["The aortic valve","The pulmonary veins","The aortic arch"],"Rotate the probe to the right from the transgastric views.","C"),
(V,"Epicardial echo during surgery is done by:","Placing a sterile-covered transducer directly on the heart",["Placing the probe in the esophagus","Using the chest wall","Using a catheter in the heart"],"It is used when TEE is not possible.","C"),
(V,"The subcostal sagittal (bicaval) view helps detect:","Sinus venosus ASDs near the SVC or IVC",["Aortic stenosis","LV mass","Coronary arteries"],"It shows both caval veins entering the RA.","C"),
(V,"A high left parasternal view (moving up one or two spaces) helps image the:","Ascending aorta",["LV apex","IVC","Abdominal aorta"],"It shows more of the aorta beyond the sinotubular junction.","F"),
(V,"A right parasternal view of the ascending aorta is useful when:","The aorta is dilated or shifted to the right",["The aorta is normal","Imaging the LV apex","Measuring the IVC"],"Patients lie on their right side for this view.","F"),
(V,"The usual order of a standard comprehensive TTE begins with:","Parasternal views, then apical, subcostal and suprasternal",["Suprasternal first","Subcostal only","TEE first"],"Follow the lab protocol for completeness.","F"),
(V,"Cine loops in sinus rhythm are usually recorded as:","At least 2 to 3 beats",["One frame","Twenty beats","One second regardless of heart rate"],"In AF, longer clips (often 5 beats or more) are needed.","F"),
(V,"In infants and children, the subcostal window is often:","The first and best window, used for situs and septal anatomy",["Never used","The worst window","Only for the aorta"],"Pediatric exams often start subcostally.","F"),
(V,"A coronary artery origin is best seen on TTE in:","The PSAX view at the aortic valve level",["The apical two-chamber view","The subcostal IVC view","The suprasternal view"],"The left main appears at about 4 o'clock and the RCA at about 10 to 11 o'clock.","C"),
(V,"When the patient cannot lie on the left side, apical images can be improved by:","Using the supine position with the arm raised and sliding laterally to find the apex",["Turning off the machine","Using a higher frequency only","Imaging only from the subcostal window"],"Each patient may need a slightly different approach.","F"),
(V,"To see the LV apex for thrombus, the sonographer should:","Use a higher-frequency setting, reduce depth, zoom and try off-axis views",["Use the lowest frequency","Increase depth to 30 cm","Only use M-mode"],"Contrast can also help.","F"),
(V,"An intraoperative TEE before cardiopulmonary bypass is used to:","Confirm the diagnosis and plan surgery",["Replace surgery","Measure blood sugar","Check lung function"],"Post-bypass TEE checks the result.","F"),
(V,"The ASE recommends that the M-mode cursor through the aortic root be placed:","Perpendicular to the aortic walls at the sinuses",["At an angle through the LVOT","At the pulmonic valve","In the LA only"],"2D measurements are preferred when M-mode cannot be placed correctly.","F"),
(V,"When the IVC cannot be seen from the subcostal window, an alternative is:","A right lateral (transhepatic) coronal view",["The suprasternal view","PLAX","Apical two-chamber"],"The liver gives a window from the side.","C"),
(V,"An apical view in which the LV appears to be tilted and the aortic valve is not seen may be corrected by:","Tilting the transducer anteriorly to bring in the LVOT for a five-chamber view",["Tilting posteriorly","Moving to the subcostal window","Increasing gain only"],"Small adjustments make a big difference in apical views.","F"),
# --- Stress echo ---
(S,"A treadmill stress echo is stopped for a systolic BP over about:","250 mmHg",["150 mmHg","120 mmHg","100 mmHg"],"Diastolic over about 115 mmHg is also an endpoint.","C"),
(S,"During DSE, the LV cavity often becomes very small with a high gradient in some patients. This is called:","Dynamic LVOT obstruction from dobutamine",["Ischemia","Normal response always","Aortic stenosis"],"It can cause hypotension and should not be mistaken for ischemia.","C"),
(S,"A 'positive' exercise ECG with normal stress echo wall motion is most often:","A false-positive ECG",["Proof of severe disease","Always a missed MI","A reason to repeat every week"],"Stress echo has better specificity than the ECG alone.","C"),
(S,"Recovery images at the end of DSE are useful to:","Show that wall motion returns to normal and catch abnormalities missed at peak",["Measure LV mass","Replace peak images","Check the aorta"],"Ischemia may persist briefly into recovery.","F"),
(S,"For a stress echo in a patient with a pacemaker, the heart rate can be raised by:","Reprogramming the pacemaker to pace at higher rates",["Turning off the echo machine","Giving beta-blockers","Lying flat only"],"This is called pacing stress echo.","C"),
(S,"Dobutamine stress echo results are interpreted with:","Wall motion at each stage, heart rate, BP, ECG and symptoms",["Only heart rate","Only blood pressure","Only ECG"],"All findings together decide the result.","F"),
]
